// ===============================================================================
// DAEMIND SRE - PARSER CANÔNICO DE LOGÍSTICA (MELHOR ENVIO, FRENET, CORREIOS, JADLOG)
// ===============================================================================
const crypto = require('crypto');
const body = $json.body || $json;

const recipient = body.to || body.destinatario || body.recipient || {};
let rawPhone = (recipient.phone || body.phone || '').toString().replace(/\D/g, '');
if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

const clienteNome = (recipient.name || 'Cliente').trim();
const trackingCode = (body.tracking || body.tracking_code || body.codigo_rastreio || body.protocol || 'RASTREIO_PENDENTE').toString().trim().toUpperCase();
const carrier = (body.agency?.name || body.carrier || body.transportadora || 'Correios/Jadlog').trim();
const numeroPedido = parseInt(body.order_id || body.numero_pedido || body.id || Date.now(), 10);

const dedupHash = crypto.createHash('sha256').update(`logistica_${trackingCode}_${numeroPedido}`).digest('hex');

return [{
  json: {
    dedup_hash: dedupHash,
    tracking_code: trackingCode,
    carrier: carrier,
    numero_pedido: numeroPedido,
    cliente_nome: clienteNome,
    cliente_whatsapp: rawPhone
  }
}];
